; flags.asm -- chapter 39: where the coincidence flag comes
; generated by gen39.py
        INCLUDE "msx.inc"
        OUTPUT "flags.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; Ten scenes of sprites, two frames each, and the status read after each:
; C, bit 5, says that two sprites' pixels met in the picture.
stat    EQU VARS                ; the status the interrupt routine read
ticks   EQU VARS + 1            ; frames, two bytes
names   EQU $C400               ; the copy of the 768 names
copy    EQU $C800               ; the copy of the sprites' attributes
ATT_TABLE EQU $1B00
PAT_TABLE EQU $3800
END_MARK EQU $D0                ; a Y of 208 ends the table
log     EQU VARS + 3            ; the status after each scene, 10 bytes
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $1B00        ; no sprites
        ld a, END_MARK
        out (VDP_DATA), a
        VRAM_WRITE $0000        ; the shapes: all paper ...
        ld bc, 2048
.shp:   xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .shp
        VRAM_WRITE $0008        ; ... but name 1, the brick
        ld hl, brick
        ld bc, (8 << 8) | VDP_DATA
        otir
        VRAM_WRITE $2000        ; the colours: black on white ...
        ld bc, 2048
.col:   ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .col
        VRAM_WRITE $2008        ; ... but the brick's
        ld hl, brick + 8
        ld bc, (8 << 8) | VDP_DATA
        otir
        VRAM_WRITE PAT_TABLE    ; the sprite patterns
        ld hl, patterns
        ld bc, (96 << 8) | VDP_DATA
        otir
        ld hl, blank            ; the names, into their copy ...
        ld de, names
        ld bc, 768
        ldir
        VRAM_WRITE $1800        ; ... and from there to the VDP
        ld hl, names
        ld bc, 768
.nam:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .nam
        ld hl, 0
        ld (ticks), hl
        ld a, END_MARK          ; no sprites in the copy yet
        ld (copy), a
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        in a, (VDP_CTRL)        ; F cleared: the first interrupt ends a frame
        VDP_REG 1, $E2          ; display on, interrupt on, sprites 16 x 16
        ei
        ld hl, scenes
        ld de, log
        ld b, 10
.scene: push bc
        push de
        ld de, copy             ; the scene's sprites into the copy
        ld bc, 25
        ldir
        ld b, 2                 ; two frames: the first sends the scene, the
.frame: call wait               ; second reads the status of a picture of it
        djnz .frame
        pop de
        ld a, (stat)
        ld (de), a              ; the status after the scene
        inc de
        pop bc
        djnz .scene
        ld a, END_MARK          ; no sprites
        ld (copy), a
done:   jr done

; isr: every frame. The status kept in stat, the copy of the sprites'
; attributes sent (the paper is over: at full speed, chapter 20), the frame
; counted. Keeps AF, BC, HL
isr:    push af
        push bc
        push hl
        in a, (VDP_CTRL)        ; the status: F, 5S and C; the signal down
        ld (stat), a
        VRAM_WRITE ATT_TABLE
        ld hl, copy
        ld bc, (25 << 8) | VDP_DATA
        otir
        ld hl, (ticks)
        inc hl
        ld (ticks), hl
        pop hl
        pop bc
        pop af
        ei
        ret

; wait: until the interrupt routine has counted a frame. Keeps BC, DE
wait:   push hl
        ld hl, ticks
        ld a, (hl)
.same:  cp (hl)                 ; the same frame: wait on
        jr z, .same
        pop hl
        ret
brick:  db $FF, $80, $80, $80, $FF, $08, $08, $08
        db $14, $14, $14, $14, $14, $14, $14, $14
patterns:                       ; ball 0, face 4, inside of the face 8
        db $00, $07, $0F, $1F, $3F, $7F, $7F, $7F
        db $7F, $7F, $7F, $3F, $1F, $0F, $07, $00
        db $00, $E0, $F0, $F8, $FC, $FE, $FE, $FE
        db $FE, $FE, $FE, $FC, $F8, $F0, $E0, $00
        db $07, $18, $20, $40, $46, $86, $80, $80
        db $80, $88, $47, $40, $20, $18, $07, $00
        db $E0, $18, $04, $02, $62, $61, $01, $01
        db $01, $11, $E2, $02, $04, $18, $E0, $00
        db $00, $07, $1F, $3F, $39, $79, $7F, $7F
        db $7F, $77, $38, $3F, $1F, $07, $00, $00
        db $00, $E0, $F8, $FC, $9C, $9E, $FE, $FE
        db $FE, $EE, $1C, $FC, $F8, $E0, $00, $00
scenes:
; scene 0: apart
        db $57, $64, $00, $01, $57, $78, $00, $04, $D0, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
; scene 1: overlap
        db $57, $64, $00, $01, $57, $6C, $00, $04, $D0, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
; scene 2: one colour 0
        db $57, $64, $00, $01, $57, $6C, $00, $00, $D0, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
; scene 3: both colour 0
        db $57, $64, $00, $00, $57, $6C, $00, $00, $D0, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
; scene 4: below the paper
        db $BF, $64, $00, $01, $BF, $6C, $00, $04, $D0, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
; scene 5: fifth and sixth
        db $57, $00, $00, $01, $57, $18, $00, $01, $57, $30, $00, $01, $57, $48, $00, $01, $57, $64, $00, $01, $57, $6C, $00, $04, $D0
; scene 6: left of the paper
        db $57, $0A, $00, $81, $57, $12, $00, $84, $D0, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
; scene 7: right of the paper
        db $57, $FA, $00, $01, $57, $FF, $00, $04, $D0, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
; scene 8: after the end
        db $D0, $00, $00, $00, $57, $64, $00, $01, $57, $6C, $00, $04, $D0, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
; scene 9: the face's two
        db $57, $64, $04, $01, $57, $64, $08, $03, $D0, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
blank:  ds 768, 0               ; no tiles: every name 0, the paper
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
